solutionCode.python:
a, b, c = map(int, input().split())

# Une note est au milieu si elle se trouve entre les deux autres.
if b <= a <= c or c <= a <= b:
    print(a)
elif a <= b <= c or c <= b <= a:
    print(b)
else:
    print(c)

solutionCode.cpp:
#include <iostream>
using namespace std;

int main() {
    int a, b, c;
    cin >> a >> b >> c;
    // Une note est au milieu si elle se trouve entre les deux autres.
    // En C++, « b <= a <= c » s'écrit b <= a && a <= c.
    if ((b <= a && a <= c) || (c <= a && a <= b)) {
        cout << a << "\n";
    } else if ((a <= b && b <= c) || (c <= b && b <= a)) {
        cout << b << "\n";
    } else {
        cout << c << "\n";
    }
    return 0;
}

